function moveWindow(win,handle,side){handle.onpointerdown=e=>{if(e.target.closest('button,select'))return;const r=win.getBoundingClientRect(),x=e.clientX,y=e.clientY;handle.setPointerCapture(e.pointerId);handle.onpointermove=v=>{let dx=v.clientX-x,dy=v.clientY-y,l=r.left,t=r.top,w=r.width,h=r.height;if(!side){l+=dx;t+=dy}else{if(side.includes('w')){l+=dx;w-=dx}else w+=dx;if(side.includes('n')){t+=dy;h-=dy}else h+=dy}w=Math.min(innerWidth-8,Math.max(250,w));h=Math.min(innerHeight-8,Math.max(180,h));Object.assign(win.style,{margin:'0',right:'auto',bottom:'auto',left:Math.max(4,Math.min(innerWidth-w-4,l))+'px',top:Math.max(4,Math.min(innerHeight-h-4,t))+'px',width:w+'px',height:h+'px'})};handle.onpointerup=()=>handle.onpointermove=null}}
